flow.typescript:
// D26 · Part 0~6 · 오늘의 흐름 전체: 20 ms 조각 → 흔들리는 네트워크 → 지터 버퍼 → 재생 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d26_flow.ts
//   프레임 계산 → 지연·지터 흉내 → 지터 버퍼 → 늦은 조각 비율 → 종단 지연을 한 번에 확인
const SR = 16000;
const FRAME_MS = 20;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function lcg(seed: number): () => number {
  // 항상 같은 순서로 나오는 0~1 난수 (대체: 실제 인터넷 대신 난수)
  let s = seed;
  return () => {
    s = (Math.imul(s, 1103515245) + 12345) & 0x7fffffff;
    return s / 0x7fffffff;
  };
}

function network(n: number, baseMs: number = 40, jitterMs: number = 30, seed: number = 7): { send: number[]; arrival: number[] } {
  // n개 조각의 (보낸 시각, 도착 시각) ms. 지연 = 기본 + 0~jitter 사이 들쭉날쭉
  const rnd = lcg(seed);
  const send = Array.from({ length: n }, (_, i) => i * FRAME_MS);
  return { send, arrival: send.map((s) => s + baseMs + rnd() * jitterMs) };
}

function percentile(xs: number[], p: number): number {
  const a = [...xs].sort((x, y) => x - y);
  const k = (a.length - 1) * (p / 100);
  const lo = Math.floor(k);
  return a[lo] + (a[Math.min(lo + 1, a.length - 1)] - a[lo]) * (k - lo);
}

const frame = Math.floor((SR * FRAME_MS) / 1000); // 1) 한 조각 = 320 샘플
const kbps = (SR * 16) / 1000; // 2) 16bit PCM 비트레이트 = 256 kbps
const { send, arrival } = network(500);
const delay = arrival.map((a, i) => a - send[i]);
const minDelay = Math.min(...delay);
const bufferMs = percentile(delay.slice(0, 50), 95) - minDelay; // 3) 처음 50개로 정한 지터 버퍼(ms)
let lateCount = 0;
for (let i = 50; i < 500; i++) if (arrival[i] > send[i] + minDelay + bufferMs) lateCount++; // 4~5) 늦은 조각
const late = lateCount / 450;
const e2e = FRAME_MS + delay.reduce((a, b) => a + b, 0) / delay.length + bufferMs; // 6) 종단 지연
console.log(`조각 ${frame}샘플 · ${kbps}kbps · 버퍼 ${bufferMs.toFixed(1)}ms · 늦은 조각 ${(late * 100).toFixed(1)}% · 종단 지연 ${e2e.toFixed(0)}ms`);
check(frame === 320 && kbps === 256 && late < 0.15 && e2e < 300, "프레임·비트레이트·늦은 비율을 확인하세요.");

frame.typescript:
// D26 · Part 1 · 프레임 계산기: 조각 크기와 비트레이트 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d26_frame.ts
//   프레임 길이(ms) → 샘플 수 · 바이트 · 초당 조각 수 · PCM 비트레이트
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface FrameInfo {
  samples: number;
  bytes: number;
  fps: number;
  kbps: number;
}

function frameInfo(sr: number, frameMs: number, bits: number = 16, channels: number = 1): FrameInfo {
  // 한 조각의 크기와 비트레이트를 계산한다
  const samples = Math.floor((sr * frameMs) / 1000); // 빈칸 1: 샘플 수 = SR x 시간
  return { samples, bytes: ((samples * bits) / 8) * channels, fps: Math.floor(1000 / frameMs), kbps: (sr * bits * channels) / 1000 };
}

for (const ms of [10, 20, 40, 200]) {
  const f = frameInfo(16000, ms);
  console.log(`${String(ms).padStart(3)} ms → ${f.samples}샘플 ${f.bytes}바이트 초당 ${f.fps}조각 ${f.kbps}kbps`);
}

const f20 = frameInfo(16000, 20);
const f48 = frameInfo(48000, 20); // Opus·WebRTC 표준 48 kHz
check(f20.samples === 320 && f20.bytes === 640 && f20.fps === 50 && f20.kbps === 256 && f48.samples === 960, "16 kHz 20 ms는 320샘플·640바이트·256 kbps예요.");

stream.typescript:
// D26 · Part 1 · batch vs streaming: 같은 말에서 '말 시작'을 언제 알 수 있나 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d26_stream.ts   (소리는 코드 안에서 합성해요)
//   32 ms(512샘플) 조각마다 에너지로 말 시작을 찾는 스트리밍 vs 파일이 끝나야 아는 batch
const SR = 16000;
const CH = 512;
const START_SEC = 0.8;
const TOTAL_SEC = 3.0;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

// 합성 신호: 0~0.8초 작은 잡음, 0.8~2.2초 '말'(220 Hz 사인), 이후 잡음 (대체: Silero VAD 대신 에너지 기준)
let seed = 1;
const noise = (): number => {
  seed = (Math.imul(seed, 1103515245) + 12345) & 0x7fffffff;
  return seed / 0x7fffffff - 0.5;
};
const y = new Float32Array(Math.floor(SR * TOTAL_SEC));
for (let i = 0; i < y.length; i++) {
  const t = i / SR;
  y[i] = 0.01 * noise() + (t >= START_SEC && t < 2.2 ? 0.3 * Math.sin(2 * Math.PI * 220 * t) : 0);
}

let streamAt: number | null = null;
for (let i = 0; i + CH <= y.length; i += CH) {
  // 32 ms씩 흘려보내기
  let e = 0;
  for (let j = i; j < i + CH; j++) e += y[j] * y[j];
  if (Math.sqrt(e / CH) > 0.05) {
    // 조각 에너지(RMS)가 기준을 넘으면 말 시작
    streamAt = (i + CH) / SR; // 그 조각이 도착한 시각
    break;
  }
}
const batchAt = TOTAL_SEC; // batch는 파일 끝까지 받은 뒤에야 분석 시작
console.log(`스트리밍은 ${streamAt?.toFixed(3)}초에 말 시작 감지, batch는 ${batchAt.toFixed(1)}초 이후`);
check(streamAt !== null && streamAt >= START_SEC && streamAt <= START_SEC + 0.1 && streamAt < batchAt, "말 시작 직후 조각에서 감지해야 해요.");

jitter.typescript:
// D26 · Part 2 · 지터 버퍼: 재생 지연을 키우면 늦은 조각이 줄어든다 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d26_jitter.ts   (네트워크는 코드 안에서 흉내 내요)
//   고정 지터 버퍼별 늦은 조각 비율, 그리고 처음 50개로 정하는 적응형 버퍼(95 백분위)
const FRAME_MS = 20;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function network(n: number, baseMs: number = 40, jitterMs: number = 60, seed: number = 3): { send: number[]; arrival: number[] } {
  // (보낸 시각, 도착 시각) ms. 지연 = 기본 + 0~jitter ms 난수 (대체: 실제 인터넷 대신 난수)
  let s = seed;
  const rnd = (): number => {
    s = (Math.imul(s, 1103515245) + 12345) & 0x7fffffff;
    return s / 0x7fffffff;
  };
  const send = Array.from({ length: n }, (_, i) => i * FRAME_MS);
  return { send, arrival: send.map((t) => t + baseMs + rnd() * jitterMs) };
}

function lateRatio(send: number[], arrival: number[], playDelayMs: number): number {
  // 재생 시각 = 보낸 시각 + 재생 지연. 도착이 그보다 늦으면 '늦은 조각'
  return arrival.filter((a, i) => a > send[i] + playDelayMs).length / arrival.length; // 빈칸 3
}

function percentile(xs: number[], p: number): number {
  const a = [...xs].sort((x, y) => x - y);
  const k = (a.length - 1) * (p / 100);
  const lo = Math.floor(k);
  return a[lo] + (a[Math.min(lo + 1, a.length - 1)] - a[lo]) * (k - lo);
}

const { send, arrival } = network(1000);
const ratios: Record<number, number> = {};
for (const d of [45, 60, 80, 100]) {
  ratios[d] = lateRatio(send, arrival, d);
  console.log(`고정 재생 지연 ${String(d).padStart(3)} ms → 늦은 조각 ${(ratios[d] * 100).toFixed(1)}%`);
}

const obs = arrival.slice(0, 50).map((a, i) => a - send[i]); // 처음 50개 조각의 지연
const adaptMs = percentile(obs, 95); // 빈칸 5: 95 백분위로 재생 지연 정하기
const adaptLate = lateRatio(send.slice(50), arrival.slice(50), adaptMs);
console.log(`적응형 재생 지연 ${adaptMs.toFixed(1)} ms → 늦은 조각 ${(adaptLate * 100).toFixed(1)}%`);
check(ratios[45] > ratios[60] && ratios[60] > ratios[80] && ratios[80] >= ratios[100] && ratios[100] === 0 && adaptLate < 0.15, "지연이 클수록 늦은 조각이 줄어야 해요.");

tcpudp.typescript:
// D26 · Part 2 · TCP vs UDP: 조각 하나를 잃었을 때 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d26_tcpudp.ts   (손실은 코드 안에서 흉내 내요)
//   TCP(WebSocket)는 잃은 조각을 다시 보낼 때까지 뒤 조각이 줄줄이 막히고(HOL blocking), UDP(WebRTC)는 그 조각만 버린다
const FRAME_MS = 20;
const BASE_MS = 40;
const RTO_MS = 200;
const PLAY_MS = 100;
const N = 100;
const LOST = new Set([30]); // 30번째 조각이 인터넷에서 사라졌다고 가정

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function udpArrivals(): (number | null)[] {
  // UDP: 잃은 조각은 영영 안 오고, 나머지는 제시간에 온다 (대체: 실제 소켓 대신 계산)
  return Array.from({ length: N }, (_, i) => (LOST.has(i) ? null : i * FRAME_MS + BASE_MS));
}

function tcpArrivals(): number[] {
  // TCP: 잃은 조각은 RTO 뒤 재전송, 순서를 지키려고 뒤 조각은 그 뒤에야 앱에 전달된다
  const out: number[] = [];
  let blockedUntil = 0;
  for (let i = 0; i < N; i++) {
    const t = i * FRAME_MS + BASE_MS + (LOST.has(i) ? RTO_MS : 0);
    blockedUntil = Math.max(blockedUntil, t);
    out.push(blockedUntil);
  }
  return out;
}

const udp = udpArrivals();
const tcp = tcpArrivals();
const udpBad = udp.filter((a, i) => a === null || a > i * FRAME_MS + PLAY_MS).length; // 잃었거나 늦은 조각
const tcpBad = tcp.filter((a, i) => a > i * FRAME_MS + PLAY_MS).length;
console.log(`UDP: 문제 조각 ${udpBad}개 (잃은 것 1개뿐) · TCP: 늦은 조각 ${tcpBad}개 (줄줄이 밀림)`);
check(udpBad === 1 && tcpBad > udpBad, "TCP는 뒤 조각이 함께 늦어져야 해요.");

opus.typescript:
// D26 · Part 3 · 비트레이트와 크기: 256 kbps → 24 kbps, 그리고 전화 μ-law — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d26_opus.ts   (소리는 코드 안에서 합성해요)
//   Opus 패킷 크기는 'CBR 공식(비트레이트 x 20 ms / 8)'으로 계산하고, 실제 압축 예로 μ-law(G.711)를 직접 구현해 SNR을 잰다
//   (대체: libopus 인코더 대신 공식 · 노트북은 PyAV로 진짜 Opus를 씀)
const SR = 16000;
const FRAME_MS = 20;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function packetBytes(kbps: number, frameMs: number = FRAME_MS): number {
  // CBR 인코더가 20 ms마다 내보내는 패킷 크기(바이트)
  return (kbps * 1000 * frameMs) / 1000 / 8;
}

function mulaw(y: Float32Array, mu: number = 255): Float32Array {
  // μ-law 압축 후 8bit 양자화 → 복원 (전화 G.711 방식, 64 kbps @ 8 kHz)
  return y.map((v) => {
    const c = (Math.sign(v) * Math.log1p(mu * Math.abs(v))) / Math.log1p(mu);
    const q = Math.round(c * 127) / 127;
    return (Math.sign(q) * Math.expm1(Math.abs(q) * Math.log1p(mu))) / mu;
  });
}

const pcm = (SR * 16) / 1000;
for (const kbps of [6, 12, 24, 32, 64]) {
  console.log(`Opus ${kbps} kbps → 20 ms 패킷 ${packetBytes(kbps)} B · PCM 대비 ${(pcm / kbps).toFixed(1)}배 작음`);
}

const y = new Float32Array(SR).map((_, i) => 0.3 * Math.sin((2 * Math.PI * 300 * i) / SR) + 0.1 * Math.sin((2 * Math.PI * 1200 * i) / SR));
const r = mulaw(y);
let sig = 0;
let err = 0;
for (let i = 0; i < y.length; i++) {
  sig += y[i] * y[i];
  err += (y[i] - r[i]) ** 2;
}
const snr = 10 * Math.log10(sig / err);
console.log(`μ-law 복원 SNR ${snr.toFixed(1)} dB`);
check(packetBytes(24) === 60 && (pcm / 24).toFixed(1) === "10.7" && snr > 30, "24 kbps는 20 ms에 60바이트, PCM의 약 10.7배 작아요.");

ws.typescript:
// D26 · Part 4 · WebSocket 흐름: 조각을 binary 메시지로 보내고 이벤트를 받는다 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d26_ws.ts   (서버는 같은 파일 안의 모의 서버예요)
//   RFC 6455 binary 프레임(마스크 포함)을 직접 만들고 풀어서, 클라이언트 → 서버 → 이벤트 흐름을 재현
//   (대체: 실제 TCP 소켓·WebSocket 대신 배열 큐로 메시지를 주고받음)
import { randomBytes } from "node:crypto";

const SR = 16000;
const CH = 320; // 20 ms = 320 샘플

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function wsEncode(payload: Buffer, opcode: number = 2, mask: boolean = true): Buffer {
  // WebSocket 프레임 만들기: FIN+opcode, 길이, (클라이언트→서버는 마스크 키), 데이터
  const n = payload.length;
  const m = mask ? 0x80 : 0;
  const head = n < 126 ? Buffer.from([0x80 | opcode, m | n]) : Buffer.from([0x80 | opcode, m | 126, n >> 8, n & 0xff]);
  if (!mask) return Buffer.concat([head, payload]);
  const key = randomBytes(4);
  return Buffer.concat([head, key, Buffer.from(payload.map((b, i) => b ^ key[i % 4]))]);
}

function wsDecode(frame: Buffer): { opcode: number; data: Buffer } {
  // 프레임 풀기 → (opcode, 데이터)
  const opcode = frame[0] & 0x0f;
  let n = frame[1] & 0x7f;
  const masked = (frame[1] & 0x80) !== 0;
  let pos = 2;
  if (n === 126) {
    n = frame.readUInt16BE(2);
    pos = 4;
  }
  const key = masked ? frame.subarray(pos, pos + 4) : Buffer.alloc(0);
  if (masked) pos += 4;
  const body = frame.subarray(pos, pos + n);
  return { opcode, data: masked ? Buffer.from(body.map((b, i) => b ^ key[i % 4])) : Buffer.from(body) };
}

interface Event {
  type: string;
  chunk?: number;
  chunks?: number;
}

function makeServer(outbox: Buffer[]): (frame: Buffer) => void {
  // 모의 서버: binary 조각을 받아 에너지가 크면 speech_start 이벤트(text 프레임)를 돌려준다
  let started = false;
  let count = 0;
  const send = (ev: Event): void => {
    outbox.push(wsEncode(Buffer.from(JSON.stringify(ev)), 1, false));
  };
  return (frame: Buffer): void => {
    const { opcode, data } = wsDecode(frame);
    if (opcode === 8) return send({ type: "bye", chunks: count }); // close
    count++;
    let e = 0;
    for (let i = 0; i < data.length; i += 2) e += (data.readInt16LE(i) / 32768) ** 2;
    if (!started && Math.sqrt(e / (data.length / 2)) > 0.05) {
      started = true;
      send({ type: "speech_start", chunk: count });
    }
  };
}

async function main(): Promise<void> {
  const outbox: Buffer[] = [];
  const serverOnMessage = makeServer(outbox);
  for (let i = 0; i + CH <= SR; i += CH) {
    const chunk = Buffer.alloc(CH * 2);
    for (let j = 0; j < CH; j++) {
      const t = (i + j) / SR;
      chunk.writeInt16LE(Math.round((t >= 0.4 ? 0.3 * Math.sin(2 * Math.PI * 220 * t) : 0) * 32767), j * 2); // 0.4초부터 '말'
    }
    serverOnMessage(wsEncode(chunk)); // 20 ms마다 binary 메시지 1개
    await new Promise((r) => setTimeout(r, 0)); // (실제로는 20 ms 쉬며 보냄)
  }
  serverOnMessage(wsEncode(Buffer.alloc(0), 8));
  const events: Event[] = outbox.map((f) => JSON.parse(wsDecode(f).data.toString()));
  console.log("서버 이벤트:", JSON.stringify(events));
  const big = Buffer.from("abc".repeat(100));
  const ok = events[0].type === "speech_start" && events[0].chunk === 21 && events[events.length - 1].type === "bye" && events[events.length - 1].chunks === 50;
  check(ok && wsDecode(wsEncode(big)).data.equals(big), "0.4초 = 21번째 조각에서 speech_start가 와야 해요."); // 126바이트 이상(확장 길이) 왕복
}

await main();

rtc.typescript:
// D26 · Part 5 · WebRTC 연결: offer · answer · ICE · DTLS · RTP — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d26_rtc.ts   (두 피어는 같은 파일 안의 모의 객체예요)
//   시그널링(offer/answer) → ICE 후보 짝 고르기 → DTLS 키 합의 → RTP 패킷(헤더 12바이트) 주고받기
//   (대체: 실제 WebRTC 대신 상태 기계 · 키는 sha256으로 흉내 내며 진짜 암호화 아님)
import { createHash } from "node:crypto";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const sha = (s: string): string => createHash("sha256").update(s).digest("hex");

interface Sdp {
  type: string;
  codec: string;
  candidates: string[];
  fp: string;
}

class Peer {
  name: string;
  ip: string;
  state: string = "new";
  seq: number = 0;
  key: string = "";
  fingerprint: string;

  constructor(name: string, ip: string) {
    this.name = name;
    this.ip = ip;
    this.fingerprint = sha(name).slice(0, 16);
  }

  offer(): Sdp {
    this.state = "have-local-offer";
    return { type: "offer", codec: "opus/48000", candidates: [`host ${this.ip}:5000`, "srflx 203.0.113.9:5000"], fp: this.fingerprint };
  }

  answer(offer: Sdp): Sdp {
    this.state = "have-remote-offer";
    return { type: "answer", codec: offer.codec, candidates: [`host ${this.ip}:6000`], fp: this.fingerprint };
  }

  rtp(payload: Buffer, ts: number): Buffer {
    // RTP 헤더: V=2, PT=111(Opus), 순번 seq, 타임스탬프(48 kHz 기준 20 ms = 960), SSRC
    this.seq++;
    const h = Buffer.alloc(12);
    h.writeUInt8(0x80, 0);
    h.writeUInt8(111, 1);
    h.writeUInt16BE(this.seq, 2);
    h.writeUInt32BE(ts, 4);
    h.writeUInt32BE(0x1234abcd, 8);
    return Buffer.concat([h, payload]);
  }
}

const pc1 = new Peer("pc1", "10.0.0.1");
const pc2 = new Peer("pc2", "10.0.0.2");
const offer = pc1.offer(); // 1) 시그널링: 서버(여기선 변수)를 거쳐 SDP 교환
const answer = pc2.answer(offer);
const pair = [offer.candidates[0], answer.candidates[0]]; // 2) ICE: 같은 망이면 host끼리 연결(가장 싼 길)
pc1.key = pc2.key = sha([offer.fp, answer.fp].sort().join("")); // 3) DTLS 키 합의 흉내
pc1.state = pc2.state = "connected";
const pkts = Array.from({ length: 5 }, (_, i) => pc1.rtp(Buffer.alloc(60), i * 960)); // 4) 24 kbps Opus 패킷 5개 (각 60바이트)
const seqs = pkts.map((p) => p.readUInt16BE(2));
const tsGap = pkts[1].readUInt32BE(4) - pkts[0].readUInt32BE(4);
console.log("선택된 ICE 짝:", pair.join(" ↔ "), "· 상태:", pc1.state, "· seq:", seqs.join(","), "· ts 간격:", tsGap);
check(pair[0].startsWith("host") && pc1.key === pc2.key && seqs.join() === "1,2,3,4,5" && tsGap === 960 && pkts[0].length === 72, "host 후보 · 같은 키 · seq 1씩 증가 · ts 960씩 증가가 맞아야 해요.");

choose.typescript:
// D26 · Part 6 · 무엇을 쓸까: 동시 통화 N개의 대역폭과 WebSocket vs WebRTC 고르기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d26_choose.ts   (계산만 해요)
const HEADER_BYTES = 12 + 8 + 20; // RTP + UDP + IP 헤더

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function callKbps(codecKbps: number, frameMs: number = 20): number {
  // 통화 한 방향의 실제 대역폭 = 코덱 + 패킷마다 붙는 헤더
  const pps = 1000 / frameMs;
  return codecKbps + (HEADER_BYTES * 8 * pps) / 1000;
}

function serverMbps(n: number, codecKbps: number = 24): number {
  // 서버가 N통을 받을 때: 올라오는 방향(사용자 말) + 내려가는 방향(비서 말)
  return (n * callKbps(codecKbps) * 2) / 1000;
}

function choose(browserClient: boolean, lossyNetwork: boolean, serverToServer: boolean): string {
  // 상황 → 추천 전송 방식
  if (serverToServer && !lossyNetwork) return "WebSocket";
  return browserClient || lossyNetwork ? "WebRTC" : "WebSocket";
}

console.log(`한 방향 ${callKbps(24)} kbps · 100통 ${serverMbps(100).toFixed(1)} Mbps`);
check(callKbps(24) === 40 && serverMbps(100) === 8 && choose(true, true, false) === "WebRTC" && choose(false, false, true) === "WebSocket", "24 kbps + 헤더 16 kbps = 40 kbps, 100통 양방향 8 Mbps예요.");
